#include "ksPanelFormatTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <tuple>
#include <string>
int main(){using T=ks::PanelFormatTask;using S=T::Stage;using C=T::Child;unsigned cases=0;for(unsigned kind=0;kind<4;++kind)for(unsigned input=0;input<256;++input){T t(static_cast<T::Kind>(kind));unsigned reads=0,children=0,used=0;std::vector<std::pair<int,unsigned>>writes;int signedValue=int8_t(input);unsigned abs=signedValue<0?unsigned(-signedValue):unsigned(signedValue),magnitude=kind==3?(abs>99?99:abs):input,width=kind<2?2:3,padding=kind==0?0x30:0x20;int cursor=int(width)-int(std::to_string(magnitude).size());while(t.stage()!=S::Complete){auto child=t.child();if(child!=C::None){if(children==0){if(child!=C::Decimal||t.magnitude()!=magnitude||t.width()!=width||t.padding()!=padding)throw std::runtime_error("decimal child request");t.resumeChild(cursor);}else{if(children!=1||child!=C::Text)throw std::runtime_error("text child order");t.resumeChild();}++children;continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](T::Read){return 0;},[](int32_t,uint8_t){}))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](T::Read){++reads;return input;},[&](int32_t pos,uint8_t value){writes.emplace_back(pos,value);});}std::vector<std::pair<int,unsigned>>expected;if(kind==3&&signedValue)expected.emplace_back(cursor-1,signedValue<0?0x2d:0x2b);unsigned clocks=kind<2?169:kind==2?164:217+(signedValue?9:0)+(signedValue<0?6:0)+(abs>99?3:0);if(writes!=expected||children!=2||reads!=1||used!=clocks)throw std::runtime_error("format sign/clamp/childs/lifecycle/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure panel-format properties\n";}
